// @vitest-environment node
//
// RC52 gate G9: scripts/soak/soak-monitor.py, the soak monitor and its verdict.
//
// 1. Golden fixtures (scripts/soak/fixtures/*.jsonl, regenerated by make_fixtures.py): a healthy
//    run passes, and each injected fault (fork, reorg, stalled head, finality stall, leak,
//    restart storm, wrong genesis or chain id, unreachable RPC, app exit, host sleep, head
//    spread) fails on exactly the rule that owns it.
// 2. Tripwire: every key in the shipped soak-criteria.json is live. Each one flips the verdict
//    of a fixture between PASS and FAIL on its own rule, and the table below must name every
//    key, so a new threshold cannot be added without a rule that reads it.
// 3. Fail closed: a bad criteria or explanations file is refused (exit 2); an unreadable or
//    empty samples file is a FAIL, never a PASS.
// 4. The sampler against local JSON-RPC stand-ins and a real process tree: fork, reorg on one
//    endpoint, unreachable endpoint, finalized tag refused, URL secrets kept out of the samples,
//    child processes, crash records written after the start.
import { describe, expect, it, beforeAll, afterAll, beforeEach, afterEach, vi } from "vitest";
import { execFile, spawn } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const script = path.join(here, "soak-monitor.py");
const fixtures = path.join(here, "fixtures");
const shipped = JSON.parse(fs.readFileSync(path.join(here, "soak-criteria.json"), "utf8"));
const PY = process.env.SOAK_PYTHON || "python3";
// Each verdict case starts Python once or twice; the 5 s default is too tight on a loaded host.
vi.setConfig({ testTimeout: 60_000 });

function py(args, opts = {}) {
  return new Promise((resolve) => {
    execFile(PY, args, { timeout: 60_000, ...opts }, (err, stdout, stderr) => {
      resolve({ code: err ? (typeof err.code === "number" ? err.code : 1) : 0, stdout, stderr });
    });
  });
}

let dir;
beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), "soak-monitor-"));
});
afterEach(() => fs.rmSync(dir, { recursive: true, force: true }));

const clone = (o) => JSON.parse(JSON.stringify(o));
// The fixtures are 3-hour runs; everything else is the shipped criteria.
const fixtureCriteria = () => {
  const c = clone(shipped);
  c.run.min_duration_hours = 2;
  return c;
};
function writeJson(name, obj) {
  const p = path.join(dir, name);
  fs.writeFileSync(p, JSON.stringify(obj));
  return p;
}
async function verdict(fixture, { criteria = fixtureCriteria(), explanations } = {}) {
  const out = path.join(dir, "verdict.json");
  const args = [script, "verdict", "--samples", fixture.includes("/") ? fixture : path.join(fixtures, `${fixture}.jsonl`)];
  args.push("--criteria", writeJson("criteria.json", criteria), "--out", out);
  if (explanations) args.push("--explanations", writeJson("explanations.json", explanations));
  const r = await py(args);
  const v = fs.existsSync(out) ? JSON.parse(fs.readFileSync(out, "utf8")) : null;
  return { ...r, v };
}
const failed = (v) => v.rules.filter((r) => r.status === "FAIL").map((r) => r.rule).sort();
const status = (v, rule) => v.rules.find((r) => r.rule === rule)?.status;

describe("golden fixtures", () => {
  const cases = {
    pass: [],
    "chain-only": [],
    "no-finality": [],
    fork: ["no_fork"],
    reorg: ["no_fork"],
    "reread-errored": ["no_fork"],
    "reread-carried-reorg": ["no_fork"],
    "stalled-head": ["finality", "head_advances"],
    "finality-stall": ["finality"],
    leak: ["rss_growth"],
    "restart-storm": ["sidecar_restarts"],
    "restart-once": ["sidecar_restarts"],
    "sidecar-vanished": ["sidecar_restarts"],
    "genesis-mismatch": ["chain_identity", "rpcs_agree"],
    "wrong-chain": ["chain_identity"],
    "rpc-down": ["rpc_reachable"],
    "app-exit": ["app_alive"],
    "sleep-gap": ["sampling_gaps"],
    "head-spread": ["finality", "head_advances", "rpcs_agree"],
  };
  for (const [name, want] of Object.entries(cases)) {
    it(`${name} -> ${want.length ? "FAIL on " + want.join(", ") : "PASS"}`, async () => {
      const r = await verdict(name);
      expect(r.v, r.stderr).not.toBeNull();
      expect(failed(r.v)).toEqual(want);
      expect(r.v.verdict).toBe(want.length ? "FAIL" : "PASS");
      expect(r.code).toBe(want.length ? 1 : 0);
      expect(r.stdout.split("\n")[0]).toBe(`SOAK ${r.v.verdict}`);
      for (const rule of want) expect(r.v.reasons.some((x) => x.startsWith(`${rule}: `))).toBe(true);
    });
  }

  it("a re-read that failed and was never retried successfully is not a pass", async () => {
    const { v } = await verdict("reread-errored");
    expect(v.reasons.join(" ")).toMatch(/block \d+ on rpc-a was never re-read/);
  });

  it("a failed re-read is carried forward: the healthy run's deferred check is verified", async () => {
    const { v } = await verdict("pass");
    expect(v.rules.find((r) => r.rule === "no_fork").detail).toContain("1 re-read deferred and later verified");
  });

  it("a sidecar that disappears after the warm-up without a crash record counts as a restart", async () => {
    const { v } = await verdict("sidecar-vanished");
    expect(v.reasons.join(" ")).toContain("'hermes-agent': 1");
    expect(v.reasons.join(" ")).toContain("vanished");
  });

  it("a chain-only run skips the app rules instead of passing them", async () => {
    const { v } = await verdict("chain-only");
    for (const rule of ["app_alive", "rss_growth", "fd_growth", "sidecar_restarts"]) expect(status(v, rule)).toBe("skip");
  });

  it("finality mode auto passes a chain whose finalized height stays 0, and says so", async () => {
    const { v } = await verdict("no-finality");
    expect(status(v, "finality")).toBe("ok");
    expect(v.rules.find((r) => r.rule === "finality").detail).toContain("not active");
  });

  it("the shipped criteria fail a 3-hour run on duration alone", async () => {
    const r = await verdict("pass", { criteria: clone(shipped) });
    expect(failed(r.v)).toEqual(["duration"]);
  });

  it("the committed fixtures are exactly what make_fixtures.py writes", async () => {
    const out = path.join(dir, "regen");
    const r = await py([path.join(fixtures, "make_fixtures.py"), out]);
    expect(r.code, r.stderr).toBe(0);
    const help = await py([path.join(fixtures, "make_fixtures.py"), "--help"], { cwd: dir });
    expect(help.code).toBe(0);
    expect(help.stdout).toContain("usage");
    expect(fs.existsSync(path.join(dir, "--help"))).toBe(false);
    const committed = fs.readdirSync(fixtures).filter((f) => f.endsWith(".jsonl")).sort();
    expect(fs.readdirSync(out).sort()).toEqual(committed);
    for (const f of committed) {
      expect(fs.readFileSync(path.join(out, f), "utf8"), f).toBe(fs.readFileSync(path.join(fixtures, f), "utf8"));
    }
  });
});

describe("live self-check example (r1005, 2026-10-26)", () => {
  // Samples from a real 5-minute read-only run against https://rpc.citrate.ai: the verdict
  // recomputed from them matches the committed verdict, rule by rule.
  it("recomputes the committed verdict from the committed samples", async () => {
    const ex = path.join(here, "examples", "selfcheck-r1005");
    const r = await verdict(path.join(ex, "samples.jsonl"), { criteria: clone(shipped) });
    const committed = JSON.parse(fs.readFileSync(path.join(ex, "verdict.json"), "utf8"));
    expect(r.v.rules).toEqual(committed.rules);
    expect(failed(r.v)).toEqual(["duration", "head_advances"]);
    expect(status(r.v, "no_fork")).toBe("ok");
    expect(status(r.v, "chain_identity")).toBe("ok");
  });
});

describe("restart explanations", () => {
  const one = { restarts: [{ sidecar: "citrate-node", count: 1, reason: "operator restarted the node to rotate logs" }] };

  it("an explained restart passes", async () => {
    const r = await verdict("restart-once", { explanations: one });
    expect(r.v.verdict).toBe("PASS");
  });

  it("one explanation does not cover a storm", async () => {
    const r = await verdict("restart-storm", { explanations: one });
    expect(failed(r.v)).toEqual(["sidecar_restarts"]);
    expect(r.v.reasons[0]).toContain("'citrate-node': 26");
  });

  it("a vanished sidecar can be explained like any restart", async () => {
    const r = await verdict("sidecar-vanished", {
      explanations: { restarts: [{ sidecar: "hermes-agent", count: 1, reason: "Hermes turned off by the operator (logged)" }] },
    });
    expect(r.v.verdict).toBe("PASS");
  });

  it("an explanation needs a reason", async () => {
    const r = await verdict("restart-once", {
      explanations: { restarts: [{ sidecar: "citrate-node", count: 1, reason: " " }] },
    });
    expect(r.code).toBe(2);
    expect(r.stderr).toContain("reason");
  });
});

describe("tripwire: every criteria key moves the verdict", () => {
  // key -> [fixture, rule, a value that passes, a value that fails]
  const LIVE = {
    "run.min_duration_hours": ["pass", "duration", 2, 4],
    "run.max_sample_gap_minutes": ["pass", "sampling_gaps", 5, 4],
    "chain.max_consecutive_unreachable": ["pass", "rpc_reachable", 1, 0],
    "chain.max_head_spread": ["pass", "rpcs_agree", 2, 1],
    "chain.head_window_minutes": ["pass", "head_advances", 10, 100000],
    "chain.min_blocks_per_window": ["pass", "head_advances", 260, 261],
    "chain.min_peers": ["pass", "peers", 3, 4],
    "chain.max_peers_below_minutes": ["pass", "peers", 5, 4],
    "finality.mode": ["no-finality", "finality", "auto", "required"],
    "finality.max_stall_minutes": ["pass", "finality", 5, 4],
    "app.warmup_minutes": ["pass", "rss_growth", 60, 100000],
    "app.min_post_warmup_minutes": ["pass", "rss_growth", 120, 121],
    "app.max_rss_growth_pct_per_hour": ["leak", "rss_growth", 5, 1],
    "app.max_fd_growth_pct_per_hour": ["pass", "fd_growth", 0.5, 0.4],
    "app.max_unexplained_restarts": ["restart-once", "sidecar_restarts", 1, 0],
  };

  it("the table names every key of the shipped criteria", () => {
    const keys = [];
    for (const [section, body] of Object.entries(shipped)) {
      if (body && typeof body === "object" && !Array.isArray(body)) for (const k of Object.keys(body)) keys.push(`${section}.${k}`);
    }
    expect(keys.sort()).toEqual(Object.keys(LIVE).sort());
  });

  for (const [key, [fixture, rule, good, bad]] of Object.entries(LIVE)) {
    it(`${key}: ${good} passes ${rule}, ${bad} fails it`, async () => {
      const [section, k] = key.split(".");
      const c = fixtureCriteria();
      c[section][k] = good;
      const ok = await verdict(fixture, { criteria: c });
      expect(status(ok.v, rule)).toBe("ok");
      c[section][k] = bad;
      const no = await verdict(fixture, { criteria: c });
      expect(status(no.v, rule)).toBe("FAIL");
      expect(no.v.verdict).toBe("FAIL");
    });
  }
});

describe("fails closed", () => {
  const refused = async (mutate, pattern) => {
    const c = fixtureCriteria();
    mutate(c);
    const r = await verdict("pass", { criteria: c });
    expect(r.code).toBe(2);
    expect(r.stderr).toMatch(pattern);
    expect(r.v).toBeNull();
  };

  it("refuses an unknown criteria key", () => refused((c) => (c.chain.min_tps = 5), /unknown key/));
  it("refuses a missing criteria key", () => refused((c) => delete c.app.max_fd_growth_pct_per_hour, /missing/));
  it("refuses a negative threshold", () => refused((c) => (c.chain.min_peers = -1), />= 0/));
  it("refuses a threshold given as a string", () => refused((c) => (c.chain.min_peers = "3"), />= 0/));
  it("refuses an unknown finality mode", () => refused((c) => (c.finality.mode = "maybe"), /one of/));
  it("refuses another criteria version", () => refused((c) => (c.version = 2), /version/));
  it("refuses an unknown section", () => refused((c) => (c.extra = {}), /unknown section/));

  it("a samples file with an unreadable line is a FAIL", async () => {
    const p = path.join(dir, "garbled.jsonl");
    fs.writeFileSync(p, fs.readFileSync(path.join(fixtures, "pass.jsonl"), "utf8") + '{"kind":"sample","seq":\n');
    const r = await verdict(p);
    expect(r.v.verdict).toBe("FAIL");
    expect(r.v.reasons.join(" ")).toContain("not valid JSON");
  });

  it("an empty samples file is a FAIL", async () => {
    const p = path.join(dir, "empty.jsonl");
    fs.writeFileSync(p, "");
    const r = await verdict(p);
    expect(r.v.verdict).toBe("FAIL");
    expect(r.code).toBe(1);
  });

  it("a header with no samples is a FAIL", async () => {
    const p = path.join(dir, "header-only.jsonl");
    fs.writeFileSync(p, fs.readFileSync(path.join(fixtures, "pass.jsonl"), "utf8").split("\n")[0] + "\n");
    const r = await verdict(p);
    expect(r.v.verdict).toBe("FAIL");
    expect(r.v.reasons[0]).toContain("no samples");
  });
});

// ---------------------------------------------------------------------------------------------
// The sampler, against JSON-RPC stand-ins.
// ---------------------------------------------------------------------------------------------

const GENESIS = "0x" + "1d".repeat(32);
const bhash = (tag, h) => "0x" + crypto.createHash("sha256").update(`${tag}:${h}`).digest("hex");

function standIn(state) {
  // state: { chainId, genesis, head, finalized ("refuse" | number), peers, tag(height, calls) }
  state.calls = 0;
  const server = http.createServer((req, res) => {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      const { id, method, params } = JSON.parse(body);
      let result = null;
      let error = null;
      if (method === "eth_chainId") {
        state.calls += 1;
        result = "0x" + state.chainId.toString(16);
      } else if (method === "eth_blockNumber") {
        const head = typeof state.head === "function" ? state.head(state.calls) : state.head;
        result = "0x" + head.toString(16);
      }
      else if (method === "net_peerCount") result = "0x" + state.peers.toString(16);
      else if (method === "eth_getBlockByNumber") {
        if (params[0] === "finalized") {
          if (state.finalized === "refuse") error = { code: -32601, message: "Method not found" };
          else result = { number: "0x" + state.finalized.toString(16), hash: bhash("main", state.finalized) };
        } else {
          const h = parseInt(params[0], 16);
          if (state.fail && state.fail(h, state.calls)) error = { code: -32000, message: "header not found" };
          else result = { number: params[0], hash: h === 0 ? state.genesis : bhash(state.tag(h, state.calls), h) };
        }
      } else error = { code: -32601, message: "Method not found" };
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify(error ? { jsonrpc: "2.0", id, error } : { jsonrpc: "2.0", id, result }));
    });
  });
  return server;
}

const listen = (server) =>
  new Promise((r) => server.listen(0, "127.0.0.1", () => r(`http://127.0.0.1:${server.address().port}`)));

const A = { chainId: 40204, genesis: GENESIS, head: 900, finalized: 880, peers: 4, tag: () => "main" };
const B = { chainId: 40204, genesis: GENESIS, head: 902, finalized: 880, peers: 4, tag: () => "main" };
let servers = [];
let urlA;
let urlB;
beforeAll(async () => {
  servers = [standIn(A), standIn(B)];
  urlA = await listen(servers[0]);
  urlB = await listen(servers[1]);
});
afterAll(() => Promise.all(servers.map((s) => new Promise((r) => s.close(r)))));
beforeEach(() => {
  Object.assign(A, { chainId: 40204, genesis: GENESIS, head: 900, finalized: 880, peers: 4, tag: () => "main", fail: null, calls: 0 });
  Object.assign(B, { chainId: 40204, genesis: GENESIS, head: 902, finalized: 880, peers: 4, tag: () => "main", fail: null, calls: 0 });
});

async function runMonitor(extra, { duration = "0", interval = "1" } = {}) {
  const out = path.join(dir, "run");
  const r = await py([
    script, "run", "--chain-id", "40204", "--genesis-hash", GENESIS,
    "--interval", interval, "--duration", duration, "--out", out, ...extra,
  ]);
  const p = path.join(out, "samples.jsonl");
  const lines = fs.existsSync(p) ? fs.readFileSync(p, "utf8").trim().split("\n").map((l) => JSON.parse(l)) : [];
  const v = fs.existsSync(path.join(out, "verdict.json")) ? JSON.parse(fs.readFileSync(path.join(out, "verdict.json"), "utf8")) : null;
  return { ...r, header: lines[0], samples: lines.slice(1), raw: fs.existsSync(p) ? fs.readFileSync(p, "utf8") : "", v };
}

describe("sampler", () => {
  it("records both endpoints and an agreeing fork check at min head - lag", async () => {
    const r = await runMonitor(["--rpc", `a=${urlA}`, "--rpc", `b=${urlB}`]);
    expect(r.header.expected).toEqual({ chain_id: 40204, genesis_hash: GENESIS });
    expect(r.samples).toHaveLength(1);
    const s = r.samples[0];
    expect(s.rpcs.map((x) => [x.label, x.ok, x.chain_id, x.genesis_hash, x.head, x.finalized, x.peers])).toEqual([
      ["a", true, 40204, GENESIS, 900, 880, 4],
      ["b", true, 40204, GENESIS, 902, 880, 4],
    ]);
    expect(s.fork_check.height).toBe(894);
    expect(s.fork_check.hashes).toEqual({ a: bhash("main", 894), b: bhash("main", 894) });
    expect(r.v.rules.find((x) => x.rule === "no_fork").status).toBe("ok");
  });

  it("sees a fork when the endpoints disagree on the hash at the common height", async () => {
    B.tag = () => "side";
    const r = await runMonitor(["--rpc", `a=${urlA}`, "--rpc", `b=${urlB}`]);
    const h = r.samples[0].fork_check.hashes;
    expect(h.a).not.toBe(h.b);
    expect(r.v.rules.find((x) => x.rule === "no_fork").status).toBe("FAIL");
    expect(r.code).toBe(1);
  });

  it("sees a reorg on a single endpoint by re-reading the previous common height", async () => {
    A.tag = (_h, calls) => (calls >= 2 ? "reorged" : "main");
    const r = await runMonitor(["--rpc", `a=${urlA}`], { duration: "1", interval: "1" });
    expect(r.samples).toHaveLength(2);
    expect(r.samples[1].fork_check.recheck).toEqual([{ label: "a", height: 894, result: "changed" }]);
    expect(r.v.reasons.join(" ")).toContain("reorg");
  });

  // The review probe: the re-read of the previous height fails once, and the chain reorgs
  // under it. The height stays the reference until a re-read succeeds, so the reorg is seen.
  it("carries a failed re-read forward and sees the reorg under it", async () => {
    A.head = (calls) => 900 + 10 * calls;
    A.fail = (h, calls) => calls === 2 && h === 904;
    A.tag = (h, calls) => (calls >= 2 && h <= 930 ? "reorged" : "main");
    const r = await runMonitor(["--rpc", `a=${urlA}`], { duration: "2", interval: "1" });
    expect(r.samples).toHaveLength(3);
    expect(r.samples[1].fork_check.recheck).toEqual([{ label: "a", height: 904, result: "unchecked" }]);
    expect(r.samples[1].fork_check.unverified).toEqual({ a: 904 });
    expect(r.samples[2].fork_check.recheck).toEqual([{ label: "a", height: 904, result: "changed" }]);
    expect(r.v.rules.find((x) => x.rule === "no_fork").status).toBe("FAIL");
    expect(r.v.reasons.join(" ")).toContain("reorg");
  });

  it("fails no_fork when the last re-read failed and nothing verified it", async () => {
    A.head = (calls) => 900 + 10 * calls;
    A.fail = (h, calls) => calls === 2 && h === 904;
    const r = await runMonitor(["--rpc", `a=${urlA}`], { duration: "1", interval: "1" });
    expect(r.samples).toHaveLength(2);
    expect(r.samples[1].fork_check.unverified).toEqual({ a: 904 });
    expect(r.v.rules.find((x) => x.rule === "no_fork").status).toBe("FAIL");
    expect(r.v.reasons.join(" ")).toContain("never re-read");
  });

  it("reports a wrong genesis and chain id as a chain_identity FAIL", async () => {
    B.genesis = "0x" + "ee".repeat(32);
    B.chainId = 1;
    const r = await runMonitor(["--rpc", `a=${urlA}`, "--rpc", `b=${urlB}`]);
    const rule = r.v.rules.find((x) => x.rule === "chain_identity");
    expect(rule.status).toBe("FAIL");
    expect(rule.detail).toContain("chain id 1");
    expect(rule.detail).toContain("genesis 0xeeee");
  });

  it("records an unreachable endpoint without stopping", async () => {
    const dead = http.createServer();
    const deadUrl = await listen(dead);
    await new Promise((res) => dead.close(res));
    const r = await runMonitor(["--rpc", `a=${urlA}`, "--rpc", `gone=${deadUrl}`]);
    const gone = r.samples[0].rpcs.find((x) => x.label === "gone");
    expect(gone.ok).toBe(false);
    expect(gone.error).toMatch(/Error/);
    expect(r.samples[0].rpcs.find((x) => x.label === "a").ok).toBe(true);
    expect(Object.keys(r.samples[0].fork_check.hashes)).toEqual(["a"]);
  });

  it("records an unknown finalized height as null, not 0", async () => {
    A.finalized = "refuse";
    const r = await runMonitor(["--rpc", `a=${urlA}`]);
    expect(r.samples[0].rpcs[0].ok).toBe(true);
    expect(r.samples[0].rpcs[0].finalized).toBeNull();
  });

  it("keeps a token in the RPC path or query out of the samples", async () => {
    const r = await runMonitor(["--rpc", `${urlA}/v1/sekrit-token?key=sekrit-key`]);
    expect(r.code).not.toBe(2);
    expect(r.header.rpcs[0]).toMatch(/^127\.0\.0\.1:\d+$/);
    expect(r.raw).not.toContain("sekrit");
  });

  it("refuses bad arguments", async () => {
    expect((await runMonitor(["--rpc", urlA, "--data-dir", dir])).code).toBe(2);
    expect((await runMonitor(["--rpc", "ftp://example.org"])).code).toBe(2);
    const bad = await py([script, "run", "--rpc", urlA, "--chain-id", "40204", "--genesis-hash", "0x12", "--out", path.join(dir, "x")]);
    expect(bad.code).toBe(2);
  });

  it("will not append to an earlier run", async () => {
    await runMonitor(["--rpc", urlA]);
    const again = await runMonitor(["--rpc", urlA]);
    expect(again.code).toBe(2);
    expect(again.stderr).toContain("exists");
  });
});

describe("sampler: the app side (a real process tree)", () => {
  let parent;
  let childPid;
  beforeEach(async () => {
    // A stand-in "app": a process whose one child is a sleep, like a supervised sidecar.
    parent = spawn(PY, ["-c", "import subprocess,time; p=subprocess.Popen(['sleep','60']); print(p.pid, flush=True); time.sleep(60)"], {
      stdio: ["ignore", "pipe", "ignore"],
    });
    childPid = Number(String(await new Promise((r) => parent.stdout.once("data", r))).trim());
  });
  afterEach(() => {
    // Both by pid: the sleep must not outlive the test, even when the test killed its parent.
    for (const pid of [childPid, parent.pid]) {
      try {
        process.kill(pid, "SIGKILL");
      } catch {
        /* already gone */
      }
    }
  });

  it("records RSS, open fds, the children and only the crash records written after the start", async () => {
    const data = path.join(dir, "app-data");
    fs.mkdirSync(path.join(data, "node"), { recursive: true });
    const later = Date.now() + 3_600_000;
    fs.writeFileSync(
      path.join(data, "node", "crash-records.jsonl"),
      [
        { name: "citrate-node", at_unix_ms: 1000, exit: "exit code: 1", stderr_tail: "", restart_attempt: 1 },
        { name: "citrate-node", at_unix_ms: later, exit: "signal: 9", stderr_tail: "", restart_attempt: 1 },
      ]
        .map((x) => JSON.stringify(x))
        .join("\n") + "\nnot json\n",
    );
    fs.writeFileSync(path.join(data, "config.json"), JSON.stringify({ name: "x", at_unix_ms: later }));
    const r = await runMonitor(["--rpc", urlA, "--pid", String(parent.pid), "--data-dir", data]);
    expect(r.header.app).toEqual({ pid: parent.pid, data_dirs: 1 });
    const app = r.samples[0].app;
    expect(app.alive).toBe(true);
    expect(app.rss_kb).toBeGreaterThan(0);
    expect(app.fds).toBeGreaterThan(0);
    expect(app.children.map((c) => c.name)).toEqual(["sleep"]);
    expect(app.crash_records).toEqual({ "citrate-node": 1 });
    expect(r.raw).not.toContain(data);
  });

  it("records a PID that is not running as not alive", async () => {
    process.kill(parent.pid, "SIGKILL");
    await new Promise((r) => parent.once("exit", r));
    const r = await runMonitor(["--rpc", urlA, "--pid", String(parent.pid)]);
    expect(r.samples[0].app.alive).toBe(false);
    expect(r.v.rules.find((x) => x.rule === "app_alive").status).toBe("FAIL");
  });
});
